INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Ermitteln des Kundenbedarfs ein zentraler Bestandteil der Kundenkommunikation?', 2, '[{"text": "Ja", "correct": true, "because": "Legt Projektgrundlage"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Ermitteln des Kundenbedarfs?', 3, '[{"text": "Kundenanforderungen klar definieren", "correct": true, "because": "Sichert Projekterfolg"}, {"text": "Projekt direkt umsetzen", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Kosten sofort senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenbedarf bildet die Basis für Ziele. b) Er wird nur im Abschluss ermittelt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, früh nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden werden zur Ermittlung des Kundenbedarfs genutzt?', 4, '[{"text": "Interviews", "correct": true, "because": "Direkte Bedarfsanalyse"}, {"text": "Unklare Annahmen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Fragebögen", "correct": true, "because": "Strukturierte Erfassung"}, {"text": "Workshops", "correct": true, "because": "Fördern Austausch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Ermittlung des Kundenbedarfs erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele unklar"}, {"text": "Ja", "correct": false, "because": "Risiko von Missverständnissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Ermitteln des Kundenbedarfs in der Initiierung?', 3, '[{"text": "Anforderungen für Planung festlegen", "correct": true, "because": "Legt Basis"}, {"text": "Team täglich steuern", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Projekt finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Ermitteln des Kundenbedarfs nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen es"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat das Projektteam bei der Bedarfserhebung?', 3, '[{"text": "Kundenanforderungen erfassen", "correct": true, "because": "Sichert Verständnis"}, {"text": "Projekt allein finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Fehler direkt beheben", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenbedarf wird mit dem Kunden abgestimmt. b) Er ist immer offensichtlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft unklar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Ermittlung des Kundenbedarfs?', 3, '[{"text": "Projektziele verfehlen Kundenwünsche", "correct": true, "because": "Fehlende Basis"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Nacharbeit"}, {"text": "Kosten sinken", "correct": false, "because": "Missverständnisse steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Kundenbedarf ohne Kommunikation ermittelt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Austausch nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt die Ermittlung des Kundenbedarfs?', 3, '[{"text": "Kunde beschreibt Anforderungen in Meeting", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas annehmen", "correct": false, "because": "Zu vage"}, {"text": "Team soll raten", "correct": false, "because": "Keine Ermittlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bedarfserhebung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team und Stakeholder beteiligt"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Ermittlung des Kundenbedarfs wichtig?', 4, '[{"text": "Kundengespräche", "correct": true, "because": "Fördern Verständnis"}, {"text": "Unklare Annahmen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Dokumentation", "correct": true, "because": "Sichert Nachweis"}, {"text": "Fragen nach Prioritäten", "correct": true, "because": "Bestimmen Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Kundenbedarf dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Bedarfserhebung?', 3, '[{"text": "Lastenheft", "correct": true, "because": "Erfasst Anforderungen"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Kundenbedarf ohne Kundeninput ermittelt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kunde liefert Basis"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Ermittlung des Kundenbedarfs?', 3, '[{"text": "Unklare Kundenangaben", "correct": true, "because": "Verhindern Klarheit"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Ablauf"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bedarfserhebung fördert Projekterfolg. b) Sie ist nur für technische Details.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Bedarfserhebung?', 3, '[{"text": "Kundenzufriedenheit erhöhen", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Abstimmung", "correct": false, "because": "Fördert Verständnis"}]');
